// Retratos generados para la demo; solo esta entrada local los incorpora.
// JPEG finales y prompts en assets/portraits/. No son datos personales.
import 'dart:convert';
import 'dart:typed_data';

const _encoded = <String, String>{
  'demo-lucia': '',
  'demo-dani': '',
  'demo-nora': '',
  'demo-marcos': '',
};
final demoPhotos = _encoded.map(
  (key, value) => MapEntry(key, base64Decode(value)),
);
Future<Uint8List> loadDemoPhoto(String path) async => demoPhotos[path]!;
